var replay = root.querySelector('.mtg-line-draw-replay');
var pts = root.querySelectorAll('.mtg-line-draw-pt');

function show(g){
  tip.textContent = g.getAttribute('data-m') + '  ' + g.getAttribute('data-v');
  tip.style.left = (parseFloat(g.getAttribute('data-x')) / 320 * 100) + '%';
  tip.style.top = (parseFloat(g.getAttribute('data-y')) / 122 * 100) + '%';
  tip.classList.add('is-on');
}
function hide(){ tip.classList.remove('is-on'); }

Array.prototype.forEach.call(pts, function(g){
  g.addEventListener('mouseenter', function(){ show(g); });
  g.addEventListener('mouseleave', hide);
  g.addEventListener('focus', function(){ show(g); });
  g.addEventListener('blur', hide);
});

replay.addEventListener('click', function(){
  hide();
  plot.classList.remove('is-play');
  void plot.offsetWidth;
  plot.classList.add('is-play');
});

