var cols = root.querySelector('.mtg-bar-stagger-cols');
var totalEl = root.querySelector('.mtg-bar-stagger-total b');
var read = root.querySelector('.mtg-bar-stagger-read');
var tabs = root.querySelectorAll('.mtg-bar-stagger-tab');
var DAYS = ['Mon','Tue','Wed','Thu','Fri','Sat','Sun'];
var SETS = [[12,18,9,24,31,6,3],[8,14,17,11,27,9,5]];
var WHEN = ['this week','last week'];
var MAX = 32, cur = 0, cells = [], raf = 0;
var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;

function peakIndex(){
  var v = SETS[cur], p = 0;
  v.forEach(function(x, i){ if (x > v[p]) p = i; });
  return p;
}
function say(i){ read.textContent = DAYS[i] + ' · ' + SETS[cur][i] + ' deploys · ' + WHEN[cur]; }
function peakSay(){ var p = peakIndex(); read.textContent = DAYS[p] + ' · ' + SETS[cur][p] + ' deploys · peak'; }

DAYS.forEach(function(d, i){
  var b = document.createElement('button');
  b.type = 'button';
  b.className = 'mtg-bar-stagger-col';
  b.innerHTML = '<span class="mtg-bar-stagger-track"><i class="mtg-bar-stagger-fill"><b>0</b></i></span><em>' + d + '</em>';
  b.addEventListener('mouseenter', function(){ say(i); });
  b.addEventListener('focus', function(){ say(i); });
  b.addEventListener('mouseleave', peakSay);
  b.addEventListener('blur', peakSay);
  cols.appendChild(b);
  cells.push(b);
});

function countTo(target){
  var from = parseInt(totalEl.textContent, 10) || 0, t0 = 0;
  if (raf) cancelAnimationFrame(raf);
  if (reduce){ totalEl.textContent = target; return; }
  function step(ts){
    if (!root.isConnected) return;
    if (!t0) t0 = ts;
    var k = Math.min(1, (ts - t0) / 700), e = 1 - Math.pow(1 - k, 3);
    totalEl.textContent = Math.round(from + (target - from) * e);
    if (k < 1) raf = requestAnimationFrame(step);
  }
  raf = requestAnimationFrame(step);
}

function render(){
  var v = SETS[cur], p = peakIndex(), sum = 0;
  v.forEach(function(x){ sum += x; });
  cells.forEach(function(b, i){
    var fill = b.querySelector('.mtg-bar-stagger-fill');
    var lab = fill.querySelector('b');
    fill.style.transitionDelay = (i * 62) + 'ms';
    fill.style.height = Math.max(3, v[i] / MAX * 100) + '%';
    lab.textContent = v[i];
    lab.style.animation = 'none';
    void lab.offsetWidth;
    lab.style.animation = '';
    lab.style.animationDelay = (i * 62 + 230) + 'ms';
    b.classList.toggle('is-peak', i === p);
  });
  countTo(sum);
  peakSay();
}

Array.prototype.forEach.call(tabs, function(t){
  t.addEventListener('click', function(){
    cur = parseInt(t.getAttribute('data-set'), 10);
    Array.prototype.forEach.call(tabs, function(o){
      var on = o === t;
      o.classList.toggle('is-on', on);
      o.setAttribute('aria-pressed', on ? 'true' : 'false');
    });
    render();
  });
});

void cols.offsetWidth;
render();

