var dial = root.querySelector('.mtg-radial-sweep-dial');
var spokes = root.querySelector('.mtg-radial-sweep-spokes');
var readH = root.querySelector('.mtg-radial-sweep-read b');
var readV = root.querySelector('.mtg-radial-sweep-read span');
var scan = root.querySelector('.mtg-radial-sweep-scan');
var NS = 'http://www.w3.org/2000/svg';
var VALS = [1.1,0.9,0.8,0.7,0.8,1.1,1.6,2.4,3.1,3.4,3.5,3.2,3.0,3.4,3.7,3.9,4.0,4.2,3.8,3.2,2.6,2.1,1.7,1.3];
var MAX = 4.4, R0 = 42, SPAN = 44, peak = 0;

VALS.forEach(function(v, i){ if (v > VALS[peak]) peak = i; });

function hh(i){ return (i < 10 ? '0' + i : i) + ':00'; }
function set(i){
  readH.textContent = hh(i);
  readV.textContent = VALS[i].toFixed(1) + 'k req';
}

VALS.forEach(function(v, i){
  var a = (-90 + i * 15) * Math.PI / 180;
  var len = R0 + Math.max(5, v / MAX * SPAN);
  var l = document.createElementNS(NS, 'line');
  l.setAttribute('x1', (100 + Math.cos(a) * R0).toFixed(1));
  l.setAttribute('y1', (100 + Math.sin(a) * R0).toFixed(1));
  l.setAttribute('x2', (100 + Math.cos(a) * len).toFixed(1));
  l.setAttribute('y2', (100 + Math.sin(a) * len).toFixed(1));
  l.setAttribute('class', 'mtg-radial-sweep-spoke' + (v >= 3.7 ? ' is-hot' : ''));
  l.style.animationDelay = (i * 0.25).toFixed(2) + 's';
  l.addEventListener('mouseenter', function(){ set(i); });
  l.addEventListener('mouseleave', function(){ set(peak); });
  spokes.appendChild(l);
});

set(peak);

scan.addEventListener('click', function(){
