var arcs = root.querySelectorAll('.mtg-donut-morph-arc');
var items = root.querySelectorAll('.mtg-donut-morph-item');
var big = root.querySelector('.mtg-donut-morph-center b');
var sub = root.querySelector('.mtg-donut-morph-center span');
var DATA = [{k:'Organic',v:1.64},{k:'Direct',v:1.05},{k:'Referral',v:0.74},{k:'Social',v:0.47}];
var on = [true,true,true,true];
var C = 2 * Math.PI * 54;

function total(){ var t = 0; DATA.forEach(function(d, i){ if (on[i]) t += d.v; }); return t; }
function base(){ big.textContent = total().toFixed(2) + 'M'; sub.textContent = 'sessions'; }
function peek(i){
  var t = total();
  if (!on[i] || t <= 0){ base(); return; }
  big.textContent = Math.round(DATA[i].v / t * 100) + '%';
  sub.textContent = DATA[i].k;
}
function paint(){
  var t = total(), acc = 0, live = 0;
  on.forEach(function(x){ if (x) live++; });
  Array.prototype.forEach.call(arcs, function(a, i){
    var s = on[i] && t > 0 ? DATA[i].v / t : 0;
    var len = s > 0 ? Math.max(0, s * C - 3) : 0;
    a.style.strokeDasharray = len.toFixed(2) + ' ' + (C - len).toFixed(2);
    a.style.strokeDashoffset = (-acc * C).toFixed(2);
    a.style.opacity = on[i] ? '1' : '0';
    acc += s;
  });
  Array.prototype.forEach.call(items, function(b, i){
    b.querySelector('em').textContent = on[i] && t > 0 ? Math.round(DATA[i].v / t * 100) + '%' : '—';
    b.setAttribute('aria-pressed', on[i] ? 'true' : 'false');
    b.disabled = live === 1 && on[i];
    b.title = b.disabled ? 'At least one source must stay on' : 'Toggle ' + DATA[i].k;
  });
  base();
}

Array.prototype.forEach.call(items, function(b, i){
  b.addEventListener('click', function(){
    if (b.disabled) return;
    on[i] = !on[i];
    paint();
  });
  b.addEventListener('mouseenter', function(){ peek(i); });
  b.addEventListener('focus', function(){ peek(i); });
  b.addEventListener('mouseleave', base);
  b.addEventListener('blur', base);
  b.addEventListener('mousedown', function(){ arcs[i].classList.add('is-lift'); });
  b.addEventListener('mouseup', function(){ arcs[i].classList.remove('is-lift'); });
  b.addEventListener('mouseleave', function(){ arcs[i].classList.remove('is-lift'); });
});

void root.offsetWidth;
paint();

