var cv = root.querySelector('.mtg-tape-scroll-canvas');
var ctx = cv.getContext('2d');
var nowWrap = root.querySelector('.mtg-tape-scroll-now');
var nowEl = nowWrap.querySelector('b');
var btn = root.querySelector('.mtg-tape-scroll-btn');
var slow = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var N = 62, STEP = slow ? 1200 : 320, TOP = 150, SLO = 90;
var buf = [], paused = false, last = 0, v = 54, w = 0, h = 0, dpr = 1;

function drift(x){
  var n = x + (Math.random() - 0.5) * 10;
  if (Math.random() < 0.05) n += 30;
  return Math.max(26, Math.min(138, n));
}
for (var i = 0; i < N; i++){ v = drift(v); buf.push(v); }

function fit(){
  var r = cv.getBoundingClientRect();
  dpr = Math.min(2, window.devicePixelRatio || 1);
  if (Math.abs(r.width - w) > 0.5 || Math.abs(r.height - h) > 0.5){
    w = r.width; h = r.height;
    cv.width = Math.max(1, Math.round(w * dpr));
    cv.height = Math.max(1, Math.round(h * dpr));
  }
}
function yOf(val){ return h - (val / TOP) * h; }

function draw(phase){
  if (!w || !h) return;
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  ctx.clearRect(0, 0, w, h);
  var step = w / (N - 3), off = -phase * step;
  ctx.lineWidth = 1;
  ctx.strokeStyle = 'rgba(120,180,215,.09)';
  for (var g = 1; g < 4; g++){
    var gy = Math.round(h * g / 4) + 0.5;
    ctx.beginPath(); ctx.moveTo(0, gy); ctx.lineTo(w, gy); ctx.stroke();
  }
  var span = step * 5;
  for (var x = off % span; x < w; x += span){
    ctx.beginPath(); ctx.moveTo(Math.round(x) + 0.5, 0); ctx.lineTo(Math.round(x) + 0.5, h); ctx.stroke();
  }
  ctx.beginPath();
  buf.forEach(function(val, i){
    var px = off + (i - 1) * step, py = yOf(val);
    if (i === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
  });
  var lastX = off + (N - 2) * step;
  ctx.lineTo(lastX, h); ctx.lineTo(off - step, h); ctx.closePath();
  var grad = ctx.createLinearGradient(0, 0, 0, h);
  grad.addColorStop(0, 'rgba(56,189,248,.34)');
  grad.addColorStop(1, 'rgba(56,189,248,0)');
  ctx.fillStyle = grad; ctx.fill();
  ctx.beginPath();
  buf.forEach(function(val, i){
    var px = off + (i - 1) * step, py = yOf(val);
    if (i === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
  });
