  ctx.strokeStyle = '#38bdf8'; ctx.stroke();
  ctx.setLineDash([4, 4]);
  ctx.strokeStyle = 'rgba(251,113,133,.55)'; ctx.lineWidth = 1;
  var sy = Math.round(yOf(SLO)) + 0.5;
  ctx.beginPath(); ctx.moveTo(0, sy); ctx.lineTo(w, sy); ctx.stroke();
  ctx.setLineDash([]);
  var head = buf[N - 1], hy = yOf(head), hot = head > SLO;
  ctx.fillStyle = hot ? '#fb7185' : '#e0f4ff';
  ctx.beginPath(); ctx.arc(lastX, hy, 2.8, 0, Math.PI * 2); ctx.fill();
  ctx.strokeStyle = hot ? 'rgba(251,113,133,.3)' : 'rgba(56,189,248,.3)';
  ctx.lineWidth = 5;
  ctx.beginPath(); ctx.arc(lastX, hy, 2.8, 0, Math.PI * 2); ctx.stroke();
}

function frame(ts){
  if (!root.isConnected) return;
  fit();
  if (!last) last = ts;
  if (paused){
    last = ts;
  } else {
    while (ts - last >= STEP){ last += STEP; v = drift(v); buf.push(v); buf.shift(); }
  }
  var phase = paused || slow ? 0 : Math.min(1, (ts - last) / STEP);
