var track = root.querySelector('.mtg-bar-race-track');
var qEl = root.querySelector('.mtg-bar-race-q');
var totEl = root.querySelector('.mtg-bar-race-tot');
var scrub = root.querySelector('.mtg-bar-race-scrub i');
var play = root.querySelector('.mtg-bar-race-btn');
var again = root.querySelector('.mtg-bar-race-btn[data-act="restart"]');
var NAMES = ['ml-serving','search-api','web-app','api-gateway','billing'];
var HUES = ['#f472b6','#38bdf8','#fbbf24','#34d399','#a78bfa'];
var QS = ['2024 Q1','2024 Q2','2024 Q3','2024 Q4','2025 Q1','2025 Q2','2025 Q3','2025 Q4'];
var F = [[40,88,132,120,96],[82,150,189,178,141],[146,231,240,236,190],[228,318,288,305,232],
         [331,402,330,372,279],[452,486,366,441,320],[588,561,401,505,358],[742,630,433,570,392]];
var ROW = 26, k = 0, paused = false, rows = [];

NAMES.forEach(function(n, i){
  var r = document.createElement('div');
  r.className = 'mtg-bar-race-row';
  r.innerHTML = '<span class="mtg-bar-race-name">' + n + '</span>' +
                '<span class="mtg-bar-race-bar"><i class="mtg-bar-race-fill"></i></span>' +
                '<span class="mtg-bar-race-num">0</span>';
  r.querySelector('.mtg-bar-race-fill').style.background = HUES[i];
  track.appendChild(r);
  rows.push(r);
});

function render(){
  var v = F[k], sum = 0, max = 0, order = [];
  v.forEach(function(x, i){ sum += x; if (x > max) max = x; order.push(i); });
  order.sort(function(a, b){ return v[b] - v[a]; });
  order.forEach(function(idx, rank){
    var r = rows[idx];
    r.style.transform = 'translateY(' + (rank * ROW) + 'px)';
    r.querySelector('.mtg-bar-race-fill').style.width = (v[idx] / max * 100).toFixed(1) + '%';
    r.querySelector('.mtg-bar-race-num').textContent = v[idx];
    r.classList.toggle('is-lead', rank === 0);
  });
  qEl.textContent = QS[k];
  totEl.textContent = sum.toLocaleString() + ' merged';
  scrub.style.width = (k / (QS.length - 1) * 100) + '%';
}

void track.offsetWidth;
render();

var timer = setInterval(function(){
  if (!root.isConnected){ clearInterval(timer); return; }
  if (paused) return;
  k = (k + 1) % QS.length;
  render();
}, 1250);

play.addEventListener('click', function(){
  paused = !paused;
  play.setAttribute('aria-pressed', paused ? 'true' : 'false');
  play.textContent = paused ? 'Play' : 'Pause';
});
again.addEventListener('click', function(){ k = 0; render(); });

