.mtg-gauge-sweep-svg{display:block;width:100%;height:auto}
.mtg-gauge-sweep-track{fill:none;stroke:rgba(255,255,255,.07);stroke-width:13;stroke-linecap:round}
.mtg-gauge-sweep-fill{fill:none;stroke:url(#mtg-gauge-sweep-grad);stroke-width:13;stroke-linecap:round;stroke-dasharray:270.2;stroke-dashoffset:270.2;transition:stroke-dashoffset .95s cubic-bezier(.3,1.05,.4,1)}
.mtg-gauge-sweep-tick{stroke:rgba(214,221,228,.22);stroke-width:1.4}
.mtg-gauge-sweep-tick.is-major{stroke:rgba(214,221,228,.5);stroke-width:2}
.mtg-gauge-sweep-needle{transform-box:view-box;transform-origin:100px 104px;transform:rotate(-90deg);transition:transform .95s cubic-bezier(.34,1.4,.5,1)}
.mtg-gauge-sweep-needle line{stroke:#eef3f7;stroke-width:3.4;stroke-linecap:round}
.mtg-gauge-sweep-val{position:absolute;left:0;right:0;bottom:11%;display:flex;align-items:baseline;justify-content:center;gap:2px;pointer-events:none}
.mtg-gauge-sweep-val b{font:600 26px/1 ui-monospace,Menlo,monospace;color:#f4f8fb;font-variant-numeric:tabular-nums}
.mtg-gauge-sweep-val i{font:600 12px/1 ui-monospace,Menlo,monospace;font-style:normal;color:#6f7c88}
.mtg-gauge-sweep-min{position:absolute;left:3%;bottom:1%;font:500 8.5px/1 ui-monospace,Menlo,monospace;color:#7c8894}
.mtg-gauge-sweep-max{position:absolute;right:3%;bottom:1%;font:500 8.5px/1 ui-monospace,Menlo,monospace;color:#7c8894}
.mtg-gauge-sweep-picks{display:flex;gap:5px;margin-top:8px}
.mtg-gauge-sweep-pick{flex:1 1 0;padding:6px 4px;border-radius:8px;border:1px solid #262c34;background:rgba(255,255,255,.03);color:#8d99a5;font:600 10px/1 system-ui,-apple-system,sans-serif;cursor:pointer;transition:background .16s ease,color .16s ease,border-color .16s ease}
.mtg-gauge-sweep-pick:hover{background:rgba(255,255,255,.09);color:#eef3f7}
.mtg-gauge-sweep-pick:active{transform:translateY(1px)}
.mtg-gauge-sweep-pick:focus-visible{outline:2px solid #7dd3fc;outline-offset:2px}
.mtg-gauge-sweep-pick.is-on{border-color:#3c4753;background:rgba(255,255,255,.12);color:#f4f8fb}
@media (prefers-reduced-motion: reduce){
.mtg-gauge-sweep-fill{transition:none}
.mtg-gauge-sweep-needle{transition:none}
.mtg-gauge-sweep-pick{transition:none}
.mtg-gauge-sweep-state{transition:none}
}

