var fill = root.querySelector('.mtg-gauge-sweep-fill');
var needle = root.querySelector('.mtg-gauge-sweep-needle');
var ticks = root.querySelector('.mtg-gauge-sweep-ticks');
var out = root.querySelector('.mtg-gauge-sweep-val b');
var state = root.querySelector('.mtg-gauge-sweep-state');
var picks = root.querySelectorAll('.mtg-gauge-sweep-pick');
var NS = 'http://www.w3.org/2000/svg';
var LEN = Math.PI * 86, shown = 0, raf = 0;
var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;

for (var i = 0; i <= 10; i++){
  var a = Math.PI + (i / 10) * Math.PI;
  var major = i % 5 === 0;
  var t = document.createElementNS(NS, 'line');
  t.setAttribute('x1', (100 + Math.cos(a) * (major ? 68 : 74)).toFixed(1));
  t.setAttribute('y1', (104 + Math.sin(a) * (major ? 68 : 74)).toFixed(1));
  t.setAttribute('x2', (100 + Math.cos(a) * 80).toFixed(1));
  t.setAttribute('y2', (104 + Math.sin(a) * 80).toFixed(1));
  t.setAttribute('class', 'mtg-gauge-sweep-tick' + (major ? ' is-major' : ''));
  ticks.appendChild(t);
}

function count(target){
  var from = shown, t0 = 0;
  if (raf) cancelAnimationFrame(raf);
  if (reduce){ shown = target; out.textContent = Math.round(target); return; }
  function step(ts){
    if (!root.isConnected) return;
    if (!t0) t0 = ts;
    var k = Math.min(1, (ts - t0) / 950), e = 1 - Math.pow(1 - k, 3);
    shown = from + (target - from) * e;
    out.textContent = Math.round(shown);
    if (k < 1) raf = requestAnimationFrame(step);
  }
  raf = requestAnimationFrame(step);
}

function set(v){
  fill.style.strokeDashoffset = (LEN * (1 - v / 100)).toFixed(2);
  needle.style.transform = 'rotate(' + (-90 + v * 1.8).toFixed(1) + 'deg)';
  root.setAttribute('data-band', v < 50 ? 'nominal' : (v < 80 ? 'elevated' : 'critical'));
  state.textContent = v < 50 ? 'nominal' : (v < 80 ? 'elevated' : 'critical');
  count(v);
}

Array.prototype.forEach.call(picks, function(b){
  b.addEventListener('click', function(){
    Array.prototype.forEach.call(picks, function(o){
      var on = o === b;
      o.classList.toggle('is-on', on);
      o.setAttribute('aria-pressed', on ? 'true' : 'false');
    });
    set(parseFloat(b.getAttribute('data-v')));
  });
});

requestAnimationFrame(function(){
  if (!root.isConnected) return;
  set(34);
});
